<?php
// Runs only in a new isolated runner WordPress database.
declare(strict_types=1);
if(rtrim(home_url(),'/')!=='http://127.0.0.1:8091'||DB_NAME!=='catalog_staging_it')throw new RuntimeException('Not isolated fixture site: '.home_url().' database='.DB_NAME);
$repo=getenv('SA_CATALOG_TEST_REPO');
require_once $repo.'/wp-content/plugins/supreme-autoparts-core/includes/product-fingerprint.php';
require_once $repo.'/wp-content/plugins/supreme-autoparts-core/includes/import-shopify.php';
$GLOBALS['sa_core_fingerprint_no_write']=true;
$transitions=[];
add_action('transition_post_status',function($new,$old,$p)use(&$transitions){if($p->post_type==='product')$transitions[]=['id'=>$p->ID,'new'=>$new,'old'=>$old];},10,3);
function fixture_ok($b,$m){if(!$b)throw new RuntimeException($m);echo "PASS $m\n";}
function fixture_item($n){return ['id'=>(string)(9000000000000+$n),'handle'=>'fixture-brace-'.$n,'title'=>'Fixture exact brace '.$n,'vendor'=>'Fixture brand','product_type'=>'Chassis Bracing','body_html'=>'Exact named brace only','tags'=>['SpecialOrder:Y','fits_2011-2021_Toyota_Aqua_NHP10'],'variants'=>[['sku'=>'FIXTURE-'.$n,'price'=>'126.00','available'=>true,'grams'=>1000]],'images'=>[['src'=>'https://cdn.shopify.com/s/files/1/0000/files/exact-fixture-'.$n.'.jpg']]];}
function fixture_import($item,$stage=true){$r=['imported'=>0,'updated'=>0,'skipped'=>0,'errors'=>0,'messages'=>[]];sa_core_import_one_shopify_product($item,$r,true,false,true,$stage);return $r;}
$item=fixture_item(1);$path='/tmp/catalog-fixture.ndjson';file_put_contents($path,json_encode($item).PHP_EOL);$r=sa_core_import_shopify_products_file($path,['skip_images'=>true,'require_images'=>true,'stage_new_only'=>true]);fixture_ok($r['errors']===0&&$r['imported']===1,'native draft create completes');$id=wc_get_product_id_by_sku('FIXTURE-1');$p=new WC_Product_Simple($id);fixture_ok($id>0&&$p->get_status()==='draft','fresh native datastore draft');fixture_ok($p->get_catalog_visibility()==='hidden','hidden native visibility');fixture_ok($p->get_regular_price()==='126.00'||(float)$p->get_regular_price()===126.0,'source price native roundtrip');fixture_ok($p->get_stock_status()==='onbackorder'&&$p->get_backorders()==='notify','native special order roundtrip');fixture_ok(get_post_meta($id,'_sa_shopify_id',true)===$item['id'],'native source metadata');fixture_ok(json_decode(get_post_meta($id,'_sa_shopify_image_urls',true),true)===[ $item['images'][0]['src'] ],'native external image metadata');fixture_ok(count(wp_get_object_terms($id,'product_cat',['fields'=>'ids']))>=2,'native category and brand assignments');fixture_ok(count(wp_get_object_terms($id,'product_tag',['fields'=>'ids']))===2,'native short source tags retained');fixture_ok(count(array_filter($transitions,fn($t)=>$t['new']==='publish'))===0,'no publish transition during draft creation');
$before=get_post($id,ARRAY_A);$meta=get_post_meta($id);$r=fixture_import($item);fixture_ok($r['errors']===1&&$r['updated']===0,'native retry existing match refused');fixture_ok(get_post($id,ARRAY_A)===$before&&get_post_meta($id)===$meta,'existing draft row/meta unchanged');
$normal=fixture_item(2);$normal['title']='Ordinary fixture mounting bracket';$r=fixture_import($normal,false);$nid=wc_get_product_id_by_sku('FIXTURE-2');fixture_ok($r['errors']===0&&get_post_status($nid)==='publish','default native import still publishes');
$alt=fixture_item(3);$alt['variants'][0]['sku']='FIXTURE-2';$r=fixture_import($alt);fixture_ok($r['errors']===1&&get_post_status($nid)==='publish','existing published SKU refused and untouched');
echo "Native draft-staging checks finished. Image bytes/sideload/hooks from full Supreme plugin/live infrastructure are not covered.\n";

$dry=fixture_item(4);file_put_contents('/tmp/catalog-dry.json',json_encode(['products'=>[$dry]]));$r=sa_core_import_shopify_products_file('/tmp/catalog-dry.json',['dry_run'=>true,'stage_new_only'=>true,'skip_images'=>true]);fixture_ok($r['imported']===1&&wc_get_product_id_by_sku('FIXTURE-4')===0,'native JSON staged dryrun no product');
require_once $repo.'/wp-content/plugins/supreme-autoparts-core/includes/cli.php';
$cli=fixture_item(5);file_put_contents('/tmp/catalog-cli.ndjson',json_encode($cli).PHP_EOL);WP_CLI::runcommand('supreme import-ndjson --file=/tmp/catalog-cli.ndjson --stage-new-only --skip-images --require-images');$cid=wc_get_product_id_by_sku('FIXTURE-5');fixture_ok($cid>0&&get_post_status($cid)==='draft','real CLI flag creates draft');
